use glam::DVec3;use ingetrazo_core::{mesh::Mesh,simplify::simplify_mesh};use serde_json::{Value,json};
fn main(){let a:Vec<_>=std::env::args().collect();let cases:Value=serde_json::from_slice(&std::fs::read(&a[1]).unwrap()).unwrap();let mut results=vec![];for c in cases.as_array().unwrap(){let mut mesh=Mesh::new();for f in c["faces"].as_array().unwrap(){let mut ring=|r:&Value|r.as_array().unwrap().iter().map(|p|mesh.add_vertex(DVec3::new(p[0].as_f64().unwrap(),p[1].as_f64().unwrap(),p[2].as_f64().unwrap()))).collect::<Vec<_>>();let vertices=ring(&f["vertices"]);let holes=f["holes"].as_array().unwrap().iter().map(&mut ring).collect();let i=mesh.add_face(vertices,holes).unwrap();mesh.faces[i].attrs=serde_json::from_value(f["attrs"].clone()).unwrap();mesh.faces[i].interior=f["interior"].as_bool().unwrap();}let(out,removed)=simplify_mesh(&mesh,c["angle"].as_f64().unwrap(),c["principal"].as_bool().unwrap()).unwrap();results.push(json!({"removed":removed,"faces":out.faces.iter().map(|f|json!({"vertices":f.vertices.iter().map(|&v|out.vertices[v].position.to_array()).collect::<Vec<_>>(),"holes":f.holes.iter().map(|h|h.iter().map(|&v|out.vertices[v].position.to_array()).collect::<Vec<_>>()).collect::<Vec<_>>(),"attrs":f.attrs,"interior":f.interior})).collect::<Vec<_>>()}));}std::fs::write(&a[2],serde_json::to_vec(&results).unwrap()).unwrap();}
